"""Reach chemistry in the ORIGINAL Upper Savannah Workspace.

This adapter uses the existing immutable object writer and source intake. It
never replaces the NDR/SDR engines, global operator, project registry or queue.
"""
from __future__ import annotations
from copy import deepcopy
import contextlib
from hashlib import sha256
import json
from pathlib import Path, PurePosixPath
import shutil
import tempfile
import zipfile

from .common import (atomic_json, canonical, digest, file_digest, held, identifier,
                     now, read_json, relative_file, verify_file, describe_file)
from .reach_chemistry.model import Project, ModelError
from .reach_chemistry.service import execute
from .reach_chemistry.solver import Cancelled
from .reach_chemistry.io import write_outputs

ENGINE_VERSION = '0.3.0'
ACTIONS = {'chemistry.case.save', 'chemistry.case.get', 'chemistry.catalog',
           'chemistry.run', 'chemistry.run.get', 'chemistry.result.page',
           'chemistry.case.from-source', 'chemistry.export', 'chemistry.receive',
           'chemistry.report.prepare', 'chemistry.report.get', 'chemistry.report.list',
           'chemistry.report.source.prepare', 'chemistry.report.source.get',
           'chemistry.report.source.list'}

class Chemistry:
    def __init__(self, workspace):
        self.ws = workspace
        self.root = workspace.root / 'chemistry-runs'

    def source_refs(self, selected):
        if not isinstance(selected, list):
            raise ModelError('source_refs must list retained Workspace source selections')
        refs, seen = [], set()
        for selection in selected:
            collection, source = selection['source_collection_id'], selection['source_id']
            key = (collection, source)
            if key in seen: continue
            seen.add(key)
            retained = self.ws._get('sources', identifier(collection))
            entry = next((item for item in retained['entries'] if item['id'] == source), None)
            if entry is None:
                raise ModelError('Choose a source retained in the selected original edition')
            records = [retained['original_manifest'], entry['body'], *entry.get('companions', [])]
            for record in records:
                verify_file(self.ws.root, {**record, 'path':record['object']})
            refs.append({'source_collection_id':collection,'source_id':source,
                         'sha256':entry['body']['sha256'], 'bytes':entry['body']['bytes'],
                         'title':entry['title'],'uri':entry['uri'],'vintage':entry['vintage']})
        return refs

    def save_case(self, value):
        project = Project(value['project'])
        if not isinstance(value.get('reason'),str) or not value['reason'].strip():
            raise ModelError('Explain the chemical scenario or scientific edit')
        sources = self.source_refs(value.get('source_refs', []))
        body = {'title':project.title,'project':project.raw,'project_sha256':project.fingerprint,
                'source_refs':sources,'reason':value['reason'],'engine_version':ENGINE_VERSION}
        if value.get('parent_id'):
            parent = self.get_case(value['parent_id'])
            body['parent_id'] = parent['id']
        if value.get('received_from'):
            body['received_from'] = deepcopy(value['received_from'])
        return self.ws._save('chemistry-cases',body)

    def from_source(self, value):
        path, entry = self.ws.source_file(value['source_collection_id'],value['source_id'])
        project = read_json(path)
        return self.save_case({'project':project,'source_refs':[value],
            'reason':value.get('reason','Imported the retained original chemistry project.')})

    def get_case(self, key):
        case = self.ws._get('chemistry-cases',identifier(key))
        project = Project(case['project'])
        if project.fingerprint != case['project_sha256']:
            raise ModelError('Saved chemistry project identity changed')
        if self.source_refs(case['source_refs']) != case['source_refs']:
            raise ModelError('A selected original source edition changed')
        return case

    def get_run(self, key):
        key = identifier(key)
        state = read_json(self.root/key/'run.json')
        if state['id'] != key or digest(state['selection']) != key:
            raise ModelError('Saved chemistry analysis selection changed')
        return state

    def catalog(self):
        cases = self.ws._list('chemistry-cases')
        runs = [self.get_run(p.parent.name) for p in sorted(self.root.glob('*/run.json'))] if self.root.exists() else []
        return {'cases':[{k:c[k] for k in ('id','title','reason','project_sha256')} for c in cases],
                'runs':[{k:r.get(k) for k in ('id','title','case_id','mode','state','progress','ended_at')} for r in runs]}

    def _verified_artifacts(self, key, state):
        directory = self.root/key
        for item in state.get('artifacts',[]): verify_file(directory,item)
        return directory

    def run(self, value, *, progress_hook=None):
        case = self.get_case(value['case_id'])
        request = deepcopy(value.get('request',{}))
        selection = {'case_id':case['id'],'project_sha256':case['project_sha256'],
                     'request':request,'engine_version':ENGINE_VERSION}
        key = digest(selection)
        directory = self.root/key
        directory.mkdir(parents=True,exist_ok=True)
        with held(directory/'.run.lock',blocking=False):
            state_file = directory/'run.json'
            if state_file.exists():
                state = self.get_run(key)
                if state['state'] == 'complete':
                    self._verified_artifacts(key,state)
                    return state
            else:
                state = {'schema':'upstate.chemistry-run/v1','id':key,'title':case['title'],
                         'case_id':case['id'],'mode':request.get('mode','simulate'),
                         'selection':selection,'created_at':now(),'state':'prepared','attempts':[]}
            state.update(state='running',started_at=now())
            state.pop('error',None)
            # Resume is an explicit user operation. A prior cancellation does not
            # keep cancelling all later attempts of the same immutable request.
            (directory/'cancel.json').unlink(missing_ok=True)
            attempt = {'started_at':state['started_at'],'number':len(state['attempts'])+1}
            state['attempts'].append(attempt)
            atomic_json(state_file,state)
            resume = None
            if state.get('checkpoint') and state['mode']=='simulate':
                checkpoint_file=verify_file(directory,state['checkpoint'])
                resume=read_json(checkpoint_file)
            def progress(event):
                state['progress']=event
                atomic_json(state_file,state)
                if progress_hook is not None: progress_hook({'run_id':key, **event})
            def checkpoint(record):
                path=directory/'checkpoints'/(digest(record)+'.json')
                atomic_json(path,record,immutable=True)
                state['checkpoint']=describe_file(directory,path)
                atomic_json(state_file,state)
            try:
                result=execute(case['project'],request,
                    cancelled=lambda:(directory/'cancel.json').exists(),
                    progress=progress,checkpoint=checkpoint,resume=resume)
                write_outputs(directory/'artifacts',case['project'],result,request)
                state['artifacts']=[describe_file(directory,p) for p in sorted((directory/'artifacts').iterdir()) if p.is_file()]
                if result.get('calibrated_project'):
                    fitted=self.save_case({'project':result['calibrated_project'],
                        'reason':'Parameter fit using retained observations in chemistry analysis '+key,
                        'source_refs':case['source_refs'],'parent_id':case['id']})
                    state['calibrated_case_id']=fitted['id']
                state.update(state='complete',ended_at=now())
                attempt.update(state='complete',ended_at=state['ended_at'])
            except BaseException as error:
                state.update(state='cancelled' if isinstance(error,Cancelled) else 'failed',
                             error={'type':type(error).__name__,'message':str(error)},ended_at=now())
                attempt.update(state=state['state'],ended_at=state['ended_at'],error=state['error'])
                atomic_json(state_file,state)
                raise
            atomic_json(state_file,state)
            return state

    def request_cancel(self,key):
        state=self.get_run(key)
        if state['state']=='running':
            atomic_json(self.root/identifier(key)/'cancel.json',{'requested_at':now()})
        return {'run_id':key,'state':state['state'],'cancellation_requested':state['state']=='running'}

    def result_page(self,value):
        key=identifier(value['run_id']); state=self.get_run(key)
        if state['state']!='complete': raise ModelError('Finish or resume the selected chemistry run')
        directory=self._verified_artifacts(key,state)
        result=read_json(directory/'artifacts/result.json')
        # Explicit collections, not arbitrary paths or arbitrary attribute reads.
        field=value.get('field') or 'final'
        allowed={'final','samples','budgets','reactions','boundary_export_by_state',
                 'observations','scores','interval_scores','parameters','rows','selected','summaries','sources'}
        if field not in allowed: raise ModelError('Choose a documented chemistry result collection')
        source=result.get('baseline',result)
        rows=result.get(field,source.get(field,[]))
        if not isinstance(rows,list): raise ModelError('The selected result is not a row collection')
        offset=value.get('offset',0); limit=value.get('limit',200)
        if type(offset)!=int or offset<0 or type(limit)!=int or not 1<=limit<=1000:
            raise ModelError('Use a nonnegative row offset and a page size from 1 to 1000')
        end=min(len(rows),offset+limit)
        return {'run_id':key,'field':field,'total':len(rows),'offset':offset,'rows':rows[offset:end],
                'next_offset':end if end<len(rows) else None}

    def artifact(self,key,name):
        state=self.get_run(key)
        if state['state']!='complete': raise ModelError('The analysis has not completed')
        expected=next((x for x in state['artifacts'] if x['path']=='artifacts/'+name),None)
        if expected is None: raise ModelError('Choose an original exported artifact')
        return verify_file(self.root/key,expected)

    def export(self, value):
        case=self.get_case(value['case_id'])
        run_ids=list(dict.fromkeys(value.get('run_ids',[])))
        selected=[]
        for rid in run_ids:
            run=self.get_run(rid)
            if run['case_id']!=case['id'] or run['state']!='complete':
                raise ModelError('Export only completed runs of the selected original case')
            self._verified_artifacts(rid,run); selected.append(run)
        selection={'case_id':case['id'],'run_ids':run_ids,'engine_version':ENGINE_VERSION}
        key=digest(selection); directory=self.ws.root/'chemistry-exports'/key
        directory.mkdir(parents=True,exist_ok=True)
        archive=directory/'editable-chemistry.zip'
        with held(directory/'.export.lock',blocking=False):
            receipt=directory/'export.json'
            if receipt.exists():
                existing=read_json(receipt)
                verify_file(self.ws.root,existing['artifact'])
                return existing
            with tempfile.TemporaryDirectory(dir=directory,prefix='.export-') as tmp:
                root=Path(tmp); atomic_json(root/'case.json',case)
                sources=[]; entries=[]
                for i,ref in enumerate(case['source_refs']):
                    original_path,entry=self.ws.source_file(ref['source_collection_id'],ref['source_id'])
                    body=deepcopy(entry); companions=body.pop('companions',[]); main=body.pop('body')
                    prefix='sources/'+str(i)+'/'
                    main_name=main.get('view_path',main['filename'])
                    target=root/prefix/main_name; target.parent.mkdir(parents=True,exist_ok=True)
                    shutil.copyfile(original_path,target)
                    body.update(id='source-'+str(i),path=prefix+main_name,sha256=main['sha256'],companions=[])
                    for companion in companions:
                        name=companion.get('view_path',companion['filename'])
                        original=relative_file(self.ws.root,companion['object'])
                        cp=root/prefix/name; cp.parent.mkdir(parents=True,exist_ok=True); shutil.copyfile(original,cp)
                        body['companions'].append({'path':prefix+name,'sha256':companion['sha256']})
                    entries.append(body)
                    sources.append({'original':ref,'incoming_id':body['id']})
                    coll=self.ws._get('sources',ref['source_collection_id'])
                    manifest=coll.get('original_manifest')
                    if manifest:
                        target=root/'original-source-manifests'/(ref['source_collection_id']+'.json')
                        target.parent.mkdir(exist_ok=True)
                        shutil.copyfile(relative_file(self.ws.root,manifest['object']),target)
                atomic_json(root/'sources.json',{'schema':'upstate.sources/v1','title':'Retained chemistry source files',
                            'entries':entries,'notes':['Original source identities and original manifests are retained in this transfer.']})
                for run in selected:
                    for artifact in run['artifacts']:
                        src=verify_file(self.root/run['id'],artifact)
                        dst=root/'runs'/run['id']/artifact['path']; dst.parent.mkdir(parents=True,exist_ok=True)
                        shutil.copyfile(src,dst)
                    atomic_json(root/'runs'/run['id']/'run.json',run)
                files={p.relative_to(root).as_posix():{'bytes':p.stat().st_size,'sha256':file_digest(p)}
                       for p in sorted(root.rglob('*')) if p.is_file()}
                atomic_json(root/'manifest.json',{'schema':'upstate.chemistry-transfer/v1','selection':selection,
                            'source_map':sources,'files':files})
                pending=directory/'.pending.zip'
                with zipfile.ZipFile(pending,'w',compression=zipfile.ZIP_DEFLATED) as z:
                    for p in sorted(root.rglob('*')):
                        if p.is_file(): z.write(p,p.relative_to(root).as_posix())
                pending.replace(archive)
            result={'id':key,'case_id':case['id'],'artifact':describe_file(self.ws.root,archive),
                    'run_ids':run_ids,'source_count':len(case['source_refs'])}
            atomic_json(receipt,result,immutable=True)
            return result

    def receive(self,path):
        path=Path(path).resolve(strict=True)
        archive_sha=file_digest(path)
        destination=self.ws.root/'chemistry-received'/archive_sha
        destination.mkdir(parents=True,exist_ok=True)
        receipt=destination/'receiving.json'
        with held(destination/'.receive.lock',blocking=False):
            if receipt.exists():
                result=read_json(receipt); self.get_case(result['case_id']); return result
            with zipfile.ZipFile(path) as z:
                names=z.namelist()
                if len(names)!=len(set(names)): raise ModelError('Archive repeats a file name')
                for info in z.infolist():
                    name=info.filename; member=PurePosixPath(name)
                    if name in ('.receive.lock','receiving.json'): raise ModelError('Archive uses a reserved receiving-control name')
                    if member.is_absolute() or '..' in member.parts or str(member)!=name or '\\' in name or '\0' in name:
                        raise ModelError('Archive has an unsafe member name')
                    if info.is_dir() or info.flag_bits & 1 or ((info.external_attr>>16)&0o170000) not in (0,0o100000):
                        raise ModelError('Archive members must be ordinary unencrypted files')
                manifest=json.loads(z.read('manifest.json'))
                if manifest.get('schema')!='upstate.chemistry-transfer/v1': raise ModelError('Select a chemistry transfer')
                if set(names)!=set(manifest['files'])|{'manifest.json'}: raise ModelError('Archive file inventory differs')
                for name,expected in manifest['files'].items():
                    target=destination/name
                    if target.is_symlink() or not target.parent.resolve().is_relative_to(destination.resolve()):
                        raise ModelError('Receiving target leaves the selected project')
                    target.parent.mkdir(parents=True,exist_ok=True)
                    with z.open(name) as source, tempfile.NamedTemporaryFile(dir=target.parent,delete=False) as out:
                        pending=Path(out.name)
                        try:
                            shutil.copyfileobj(source,out,1024*1024); out.flush()
                        except BaseException:
                            pending.unlink(missing_ok=True); raise
                    try:
                        if pending.stat().st_size!=expected['bytes'] or file_digest(pending)!=expected['sha256']:
                            raise ModelError('Received member hash differs: '+name)
                        pending.replace(target)
                    finally: pending.unlink(missing_ok=True)
            case=read_json(destination/'case.json'); refs=[]
            if manifest['source_map']:
                collection=self.ws.import_sources(destination/'sources.json')
                refs=[{'source_collection_id':collection['id'],'source_id':m['incoming_id']} for m in manifest['source_map']]
            incoming=self.save_case({'project':case['project'],'reason':case['reason'],'source_refs':refs,
                'received_from':{'archive_sha256':archive_sha,'case_id':case['id'],
                                 'original_source_refs':case['source_refs']}})
            adopted=[]
            for old_id in manifest['selection']['run_ids']:
                identifier(old_id)
                original=read_json(destination/'runs'/old_id/'run.json')
                if (original['id']!=old_id or digest(original['selection'])!=old_id
                        or original['case_id']!=case['id'] or original['state']!='complete'
                        or original['selection']['project_sha256']!=case['project_sha256']):
                    raise ModelError('Incoming run does not belong to the received case')
                selection=deepcopy(original['selection']); selection['case_id']=incoming['id']
                new_id=digest(selection); run_dir=self.root/new_id; run_dir.mkdir(parents=True,exist_ok=True)
                with held(run_dir/'.run.lock',blocking=False):
                    if (run_dir/'run.json').exists():
                        active=self.get_run(new_id)
                        if active['state']!='complete':
                            raise ModelError('An unfinished local run already has this selection')
                        self._verified_artifacts(new_id,active)
                    else:
                        for item in original['artifacts']:
                            source=verify_file(destination/'runs'/old_id,item)
                            target=run_dir/item['path']
                            if target.is_symlink() or not target.parent.resolve().is_relative_to(run_dir.resolve()):
                                raise ModelError('Incoming artifact target leaves its run')
                            target.parent.mkdir(parents=True,exist_ok=True)
                            shutil.copyfile(source,target)
                        active={**original,'id':new_id,'case_id':incoming['id'],'selection':selection,
                                'received_from':{'archive_sha256':archive_sha,'run_id':old_id}}
                        active.pop('checkpoint',None)
                        active.pop('calibrated_case_id',None)
                        result_file=read_json(run_dir/'artifacts/result.json')
                        if result_file.get('calibrated_project'):
                            child=self.save_case({'project':result_file['calibrated_project'],
                                'source_refs':refs,'parent_id':incoming['id'],
                                'reason':'Received fitted parameter edition from '+old_id})
                            active['calibrated_case_id']=child['id']
                        atomic_json(run_dir/'run.json',active)
                adopted.append({'original_run_id':old_id,'run_id':new_id})
            result={'schema':'upstate.chemistry-receiving/v1','case_id':incoming['id'],
                    'original_case_id':case['id'],'archive_sha256':archive_sha,
                    'retained_run_ids':manifest['selection']['run_ids'], 'adopted_runs':adopted,
                    'retained_files':len(manifest['files']),
                    'directory':str(destination.relative_to(self.ws.root))}
            atomic_json(receipt,result,immutable=True)
            return result


def invoke(workspace,action,value, *, progress_hook=None):
    service=Chemistry(workspace)
    if action=='chemistry.case.save': return service.save_case(value)
    if action=='chemistry.case.from-source': return service.from_source(value)
    if action=='chemistry.case.get': return service.get_case(value['case_id'])
    if action=='chemistry.catalog': return service.catalog()
    if action in {'chemistry.report.prepare', 'chemistry.report.get', 'chemistry.report.list'}:
        from . import chemistry_reports
        if action == 'chemistry.report.prepare': return chemistry_reports.prepare(workspace, value['run_id'])
        if action == 'chemistry.report.get': return chemistry_reports.inspect(workspace, value['report_id'])
        return {'reports': chemistry_reports.catalog(workspace, value.get('run_id'))}
    if action in {'chemistry.report.source.prepare', 'chemistry.report.source.get',
                  'chemistry.report.source.list'}:
        from . import chemistry_report_source
        if action == 'chemistry.report.source.prepare':
            return chemistry_report_source.prepare(workspace, value['report_id'])
        if action == 'chemistry.report.source.get':
            return chemistry_report_source.inspect(workspace, value['source_record_id'])
        return {'report_sources': chemistry_report_source.list_saved(workspace, value.get('report_id'))}
    if action=='chemistry.run': return service.run(value,progress_hook=progress_hook)
    if action=='chemistry.run.get': return service.get_run(value['run_id'])
    if action=='chemistry.result.page': return service.result_page(value)
    if action=='chemistry.export': return service.export(value)
    if action=='chemistry.receive':
        # A source selection uses the same retained original source intake.
        path,entry=workspace.source_file(value['source_collection_id'],value['source_id'])
        return service.receive(path)
    raise ModelError('Unknown chemistry action: '+action)

"""Reopen original chemistry selections and artifacts inside workspace receiving."""
from .chemistry import Chemistry
from .common import identifier, verify_file


def verify_all(workspace):
    service = Chemistry(workspace)
    cases = {}
    for saved in workspace._list('chemistry-cases'):
        case = service.get_case(saved['id'])
        cases[case['id']] = case
    for case in cases.values():
        if case.get('parent_id') and case['parent_id'] not in cases:
            raise ValueError('Chemical scenario is missing its original parent edition')
    runs = 0
    for path in sorted(service.root.glob('*/run.json')):
        key = identifier(path.parent.name)
        run = service.get_run(key)
        case = cases.get(run['case_id'])
        selection = run['selection']
        if (case is None or selection.get('case_id') != case['id']
                or selection.get('project_sha256') != case['project_sha256']):
            raise ValueError('Chemical analysis belongs to a different retained scenario')
        if run.get('calibrated_case_id') and run['calibrated_case_id'] not in cases:
            raise ValueError('Chemical analysis is missing its calibrated scenario')
        service._verified_artifacts(key, run)
        if run.get('checkpoint'):
            verify_file(service.root / key, run['checkpoint'])
        runs += 1
    from .chemistry_reports import verify_all as verify_reports
    reports = verify_reports(workspace)
    from .chemistry_report_source import verify_workspace
    report_sources = verify_workspace(workspace)
    return {'cases': len(cases), 'runs': runs, 'scientific_reports': reports['reports'],
            'scientific_report_sources': report_sources}

"""Scientific presentation of original completed reach-chemistry results.

This module reads retained result fields. It does not fit coefficients, propagate
the network, estimate uncertainty or change any original observation.
"""
from __future__ import annotations

import html
import json
import math

from .inference import observation_key

REPORT_EDITION = "reach-chemistry-scientific-report/3"
PARAMETER_UNITS = {
    "reaction_rate_day": "day^-1",
    "load_kg_day": "kg of declared basis/day",
    "boundary_mg_l": "mg of declared basis/L",
    "initial_kg": "kg of declared basis",
}


def _text(value):
    if value is None:
        return "Not supplied"
    if isinstance(value, bool):
        return "Yes" if value else "No"
    if isinstance(value, float):
        return format(value, ".12g")
    if isinstance(value, (dict, list)):
        return json.dumps(value, ensure_ascii=False, sort_keys=True, allow_nan=False)
    return str(value)


def _escape(value):
    return html.escape(_text(value), quote=True)


def _table(rows, fields, caption):
    if not rows:
        return "<p>No records in this retained result.</p>"
    return ("<div class='scroll'><table><caption>" + _escape(caption)
            + "</caption><thead><tr>"
            + "".join("<th scope='col'>" + _escape(label) + "</th>" for _, label in fields)
            + "</tr></thead><tbody>"
            + "".join("<tr>" + "".join("<td>" + _escape(row.get(key)) + "</td>"
                                       for key, _ in fields) + "</tr>" for row in rows)
            + "</tbody></table></div>")


def _items(values, caption):
    return _table([{"item": key, "value": value} for key, value in values],
                  [("item", "Item"), ("value", "Retained value")], caption)


def _provenance(value):
    value = value if isinstance(value, dict) else {}
    return {"source_kind": value.get("kind"), "source_reference": value.get("reference"),
            "source_detail": value}


def _observation_operator(project, row):
    """Describe the retained single-species or same-basis observation operator."""
    sid = row.get("species")
    if isinstance(sid, str) and sid in project.species:
        # Legacy output is interpreted exactly as its original single-species
        # engine. Unused request metadata must not change old result semantics.
        species = project.species[sid]
        return {"identity": {"kind": "species", "species": sid, "basis": species["basis"]},
                "label": _text(species.get("name") or sid), "basis": species["basis"], "expression": sid}
    components = row.get("components")
    if components is not None:
        if row.get("species") is not None:
            raise ValueError("A composite Chemistry observation must not name a single species")
        measurement, basis = row.get("measurement"), row.get("basis")
        if (not isinstance(measurement, str) or not measurement.strip()
                or not isinstance(basis, str) or not basis
                or not isinstance(components, list) or not components):
            raise ValueError("A composite Chemistry observation needs its original measurement, basis and components")
        seen, canonical, expression = set(), [], []
        for item in components:
            if not isinstance(item, dict):
                raise ValueError("An original Chemistry observation component must be an object")
            sid, weight = item.get("species"), item.get("weight")
            if (not isinstance(sid, str) or sid not in project.species or sid in seen
                    or isinstance(weight, bool) or not isinstance(weight, (int, float))
                    or not math.isfinite(weight) or weight <= 0):
                raise ValueError("Original Chemistry observation weights require unique species and positive finite values")
            if project.species[sid]["basis"] != basis:
                raise ValueError("A composite Chemistry observation combines different conserved bases")
            seen.add(sid)
            canonical.append({"species": sid, "weight": float(weight)})
            expression.append(_text(weight) + " × " + sid)
        identity = {"kind": "composite", "measurement": measurement, "basis": basis,
                    "components": sorted(canonical, key=lambda item: item["species"])}
        return {"identity": identity, "label": measurement, "basis": basis,
                "expression": " + ".join(expression)}
    raise ValueError("A retained Chemistry observation needs its declared species or composite operator")


def _species(project, row):
    """Keep current original operator validation and labels, with explicit interval limits."""
    if row.get("components") is not None or row.get("species") in project.species:
        operator = _observation_operator(project, row)
        value = {**row, "basis": operator["basis"], "species_label": operator["label"],
                 "measurement_label": operator["label"], "operator_label": operator["label"],
                 "operator_expression": operator["expression"]}
    else:
        sid = row.get("species")
        value = {**row, "basis": row.get("basis"), "species_label": sid,
                 "measurement_label": row.get("measurement", sid),
                 "operator_label": row.get("measurement", sid),
                 "operator_expression": row.get("measurement", sid)}
    if row.get("qualifier") == "interval":
        value["declared_interval"] = (("[" if row["lower_closed"] else "(")
            + _text(row["lower_mg_l"]) + ", " + _text(row["upper_mg_l"])
            + ("]" if row["upper_closed"] else ")"))
    return value


def _observation_groups(project, rows):
    """Use the original native operator identity, including label, basis and weights."""
    groups = {}
    for row in rows:
        groups.setdefault(observation_key(row), []).append(row)
    order = {("species", sid): index for index, sid in enumerate(project.species)}
    keys = sorted(groups, key=lambda key: order.get(key, len(order)))
    return [(key, _species(project, groups[key][0]), groups[key]) for key in keys]


OBSERVATION_FIELDS = [
    ("measurement_label", "Measurement"), ("operator_expression", "Observation operator"),
    ("components", "Original components"), ("basis", "Conserved basis"),
]


def _interval_figures(project, observations):
    """Present the original limits and prediction; no point substitute is calculated."""
    figures = []
    for group_index, (_, description, retained) in enumerate(_observation_groups(project, observations)):
        rows = [row for row in retained if row.get("qualifier") == "interval"]
        for start in range(0, len(rows), 12):
            subset = rows[start:start + 12]
            values = [float(row[key]) for row in subset
                      for key in ("lower_mg_l", "upper_mg_l", "predicted_mg_l")]
            if any(not math.isfinite(value) for value in values):
                raise ValueError("Nonfinite original interval figure coordinates")
            low, high = min(0.0, min(values)), max(values)
            span = max(high - low, abs(high) * .05, 1e-12)
            high += span * .06
            series = []
            for index, row in enumerate(subset, 1):
                common = {"record_id": row["id"], "reach": row["reach"], "day": row["day"],
                          "role": row.get("role", "fit")}
                series.append({"geometry": "line", "label": "Declared interval" if index == 1 else "",
                    "markers": False, "points": [
                        {"x": row["lower_mg_l"], "y": index, **common},
                        {"x": row["upper_mg_l"], "y": index, **common}]})
                for bound in ("lower", "upper"):
                    series.append({"geometry": "scatter", "label": "",
                        "marker": "circle" if row[bound + "_closed"] else "square-open",
                        "points": [{"x": row[bound + "_mg_l"], "y": index, **common,
                                    "closed": row[bound + "_closed"]}]})
            series.append({"geometry": "scatter", "label": "Retained prediction", "marker": "diamond",
                "points": [{"x": row["predicted_mg_l"], "y": index, "record_id": row["id"],
                            "within_declared_interval": row.get("interval_contains_prediction")}
                           for index, row in enumerate(subset, 1)]})
            figures.append({"id": "interval-" + str(group_index + 1) + "-" + str(start + 1),
                "title": "Declared observation intervals: " + description["operator_label"],
                "caption": description["operator_expression"] + " on the " + description["basis"]
                    + " basis. Solid circles include endpoints; open squares exclude endpoints. Diamonds "
                      "show retained predictions. A prediction on an open endpoint has zero distance "
                      "penalty and remains outside the declared interval. Records: "
                    + "; ".join(str(index) + " = " + row["id"] + " (" + row.get("role", "fit") + ")"
                                for index, row in enumerate(subset, 1)) + ".",
                "panels": [{"id": "limits", "title": description["operator_label"],
                    "x": {"label": "Concentration", "unit": "mg " + description["basis"] + "/L",
                          "domain": [low, high], "ticks": [
                              {"value": low + (high - low) * i / 4,
                               "label": format(low + (high - low) * i / 4, ".4g")} for i in range(5)]},
                    "y": {"label": "Record", "unit": "index", "domain": [0, len(subset) + 1],
                          "ticks": [{"value": i, "label": str(i)} for i in range(1, len(subset) + 1)]},
                    "series": series}]})
    return figures


def _intervals(project, observations):
    figures = []
    for figure in _interval_figures(project, observations):
        panel = figure["panels"][0]
        low, high = panel["x"]["domain"]
        count = panel["y"]["domain"][1]
        X = lambda value: 60 + (value - low) / (high - low) * 490
        Y = lambda value: 60 + (count - value) / count * 320
        parts = ["<figure><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 620 460' role='img'>",
                 "<title>" + _escape(figure["title"]) + "</title><rect width='620' height='460' fill='white'/>",
                 "<g font-family='sans-serif' font-size='12' fill='#171717'>",
                 "<path d='M60 60V380H550' fill='none' stroke='#171717'/>"]
        for tick in panel["x"]["ticks"]:
            parts.append(f"<text x='{X(tick['value']):.3f}' y='402' text-anchor='middle'>"
                         + _escape(tick["label"]) + "</text>")
        for tick in panel["y"]["ticks"]:
            parts.append(f"<text x='48' y='{Y(tick['value'])+4:.3f}' text-anchor='end'>"
                         + _escape(tick["label"]) + "</text>")
        for series in panel["series"]:
            points = series["points"]
            if series["geometry"] == "line":
                coordinates = " ".join(f"{X(p['x']):.3f},{Y(p['y']):.3f}" for p in points)
                parts.append("<polyline points='" + coordinates + "' fill='none' stroke='#171717'/>")
            else:
                for point in points:
                    x, y = X(point["x"]), Y(point["y"])
                    tip = "<title>" + _escape(point) + "</title>"
                    if series["marker"] == "square-open":
                        parts.append(f"<rect x='{x-4:.3f}' y='{y-4:.3f}' width='8' height='8' fill='white' stroke='#171717'>{tip}</rect>")
                    elif series["marker"] == "diamond":
                        parts.append(f"<path d='M{x:.3f} {y-5:.3f}l5 5 -5 5 -5 -5Z' fill='#171717'>{tip}</path>")
                    else:
                        parts.append(f"<circle cx='{x:.3f}' cy='{y:.3f}' r='3' fill='#171717'>{tip}</circle>")
        parts += ["<text x='305' y='440' text-anchor='middle'>"
                  + _escape(panel["x"]["label"] + " (" + panel["x"]["unit"] + ")") + "</text>",
                  "</g></svg><figcaption>" + _escape(figure["title"] + ". " + figure["caption"]) + "</figcaption></figure>"]
        figures.append("".join(parts))
    return "<div class='figures'>" + "".join(figures) + "</div>" if figures else ""


def _parameters(project, result, request):
    original = {p["id"]: p for p in request.get("parameters", [])}
    rows = []
    for parameter in result.get("parameters", request.get("parameters", [])):
        item = {**original.get(parameter["id"], {}), **parameter}
        kind, target = item.get("kind"), item.get("target")
        group = {"reaction_rate_day": project.reactions, "load_kg_day": project.loads,
                 "boundary_mg_l": project.flows, "initial_kg": project.initials}.get(kind, {})
        physical = group.get(target, {})
        species_id = item.get("species") or physical.get("species") or physical.get("source")
        basis = project.species.get(species_id, {}).get("basis")
        if kind == "boundary_mg_l":
            basis = project.species.get(item.get("species"), {}).get("basis")
        item.update(parameter_units=PARAMETER_UNITS.get(kind, kind), basis=basis,
                    source_reference=physical.get("provenance", {}).get("reference"),
                    bound_meaning={-1: "Lower bound", 0: "Interior", 1: "Upper bound"}.get(item.get("active_bound")))
        rows.append(item)
    return rows


def summary(project, result, request=None):
    request = request or {}
    observations = result.get("observations", [])
    return {"edition": REPORT_EDITION, "title": project.title,
            "mode": request.get("mode") or result.get("schema", "").removeprefix("reach-chemistry-").split("/")[0],
            "result_schema": result.get("schema"), "project_sha256": project.fingerprint,
            "duration_days": project.end_day, "reaches": project.nr, "species": project.ns,
            "project_provenance": project.raw.get("provenance", {}),
            "fit_records": sum(r.get("role", "fit") == "fit" for r in observations),
            "held_out_records": sum(r.get("role") == "holdout" for r in observations),
            "below_limit_records": sum(r.get("qualifier") == "below" for r in observations),
            "interval_records": sum(r.get("qualifier") == "interval" for r in observations),
            "compound_records": sum("components" in r and "species" not in r for r in observations),
            "converged": result.get("converged"), "termination": result.get("termination"),
            "draw_count": result.get("draw_count"), "seed": result.get("seed"),
            "recorded_solver_elapsed_seconds": result.get("elapsed_seconds", result.get("baseline", result).get("numerics", {}).get("elapsed_seconds"))}


def _scatter(project, observations):
    """Equal-axis plot of original exact-valued reference/prediction pairs."""
    panels = []
    for _, species, retained in _observation_groups(project, observations):
        sid = species["operator_label"]
        rows = [r for r in retained if r.get("qualifier", "equal") == "equal"]
        if not rows:
            continue
        if any(not math.isfinite(float(r[key])) for r in rows for key in ("observed_mg_l", "predicted_mg_l")):
            raise ValueError("Nonfinite original chemistry scatter coordinates")
        values = [float(r[key]) for r in rows for key in ("observed_mg_l", "predicted_mg_l")]
        low, high = min(0.0, min(values)), max(values)
        span = max(high - low, abs(high) * 0.05, 1e-12)
        high += span * 0.06
        if high == low:
            high = low + 1.0
        left, top, width, height = 84, 58, 460, 460
        def x(value):
            return left + (value - low) / (high - low) * width
        def y(value):
            return top + height - (value - low) / (high - low) * height
        pieces = ["<figure><svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 620 620' role='img' aria-label='"
                  + _escape(sid + " reference and modeled concentration") + "'>",
                  "<rect width='620' height='620' fill='white'/>",
                  "<g font-family='sans-serif' fill='#171717' font-size='13'>",
                  "<text x='84' y='27' font-size='19'>" + _escape(sid + " / " + species["basis"]) + "</text>",
                  "<path d='M84 58V518H544' fill='none' stroke='#171717'/>",
                  "<path d='M84 518L544 58' fill='none' stroke='#777' stroke-dasharray='5 4'/>"]
        for i in range(6):
            value = low + (high - low) * i / 5
            xp, yp = x(value), y(value)
            label = format(value, ".4g")
            pieces += [f"<text x='{xp:.3f}' y='542' text-anchor='middle'>{label}</text>",
                       f"<text x='73' y='{yp+4:.3f}' text-anchor='end'>{label}</text>"]
        for row in rows:
            xp, yp = x(float(row["observed_mg_l"])), y(float(row["predicted_mg_l"]))
            label = _escape(row["id"] + " / " + row.get("role", "fit")
                            + " / reference " + _text(row["observed_mg_l"])
                            + " / modeled " + _text(row["predicted_mg_l"]) + " mg/L")
            if row.get("role") == "holdout":
                pieces.append(f"<rect x='{xp-4:.3f}' y='{yp-4:.3f}' width='8' height='8' fill='white' stroke='#111'><title>{label}</title></rect>")
            else:
                pieces.append(f"<circle cx='{xp:.3f}' cy='{yp:.3f}' r='3.5' fill='#333'><title>{label}</title></circle>")
        pieces += ["<text x='314' y='575' text-anchor='middle'>Original reference (mg of " + _escape(species["basis"]) + "/L)</text>",
                   "<text transform='translate(19 288) rotate(-90)' text-anchor='middle'>Modeled concentration (same units)</text>",
                   "<text x='84' y='605'>Solid circle: fit. Open square: held out. Dashed: equality.</text>",
                   "</g></svg><figcaption>" + _escape(species["operator_expression"]) + ". Equal axis ranges for this exact measurement operator. Below-limit and interval records retain their limits in the full table and interval figures.</figcaption></figure>"]
        panels.append("".join(pieces))
    return "<div class='figures'>" + "".join(panels) + "</div>" if panels else ""


